var t=`0097-kalduny`;var i=`world-0097`;var o=`BY`;var s=`eastern-europe`;var a=4;var l=41;var r={en:`Kalduny`,ua:`Калдуни`};var g={en:`A classic dish from Belarus, featuring potato, ground pork, yellow onion, chicken egg. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Білорусь. Основні складники: картопля, свинячий фарш, жовта цибуля, куряче яйце. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:9,i:[[`potato`,680,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:7,i:[[`ground-pork`,280,`g`],[`yellow-onion`,100,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`all-purpose-flour`,75,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,70,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,130,`g`]]}];var d={slug:t,id:i,country:`BY`,region:s,servings:4,minutes:41,title:r,text:g,steps:u};export{o as country,d as default,i as id,l as minutes,s as region,a as servings,t as slug,u as steps,g as text,r as title};